using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static partial class StackHouse3DSigns{
public static Mesh BuildHospitalRoadside(Material material,bool detailed){atlas=new Texture2D(2,2);atlas.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(material.GetTexture("_BaseMap"))));var g=new G();surfaceType=0;var dark=ColorUV(new Color(.045f,.055f,.07f));var red=ColorUV(new Color(.87f,.025f,.055f));var white=ColorUV(new Color(.97f,.97f,.97f));Action<float,float,float,float,float,float,float,float,float> quad=(cx,cy,w,h,z,u0,v0,u1,v1)=>{g.Quad(new Vector3(cx-w/2,cy-h/2,z),new Vector3(cx+w/2,cy-h/2,z),new Vector3(cx+w/2,cy+h/2,z),new Vector3(cx-w/2,cy+h/2,z),new Vector2(u1,v0),new Vector2(u0,v0),new Vector2(u0,v1),new Vector2(u1,v1));};
for(int side=0;side<2;side++){int start=g.p.Count;g.Box(new Vector3(0,0,.77f),new Vector3(7.91f,2.82f,.12f),dark);if(detailed){quad(-.80f,.19f,5.25f,.87f,.845f,.428f,.513f,.606f,.580f);g.Box(new Vector3(2.83f,.21f,.93f),new Vector3(1.25f,1.25f,.30f),red);g.Box(new Vector3(2.83f,.21f,1.105f),new Vector3(.30f,.91f,.07f),white);g.Box(new Vector3(2.83f,.21f,1.105f),new Vector3(.91f,.30f,.07f),white);var line=new[]{new Vector3(-3.4f,-.62f,.87f),new Vector3(-.2f,-.62f,.87f),new Vector3(-.05f,-.40f,.87f),new Vector3(.12f,-.89f,.87f),new Vector3(.29f,-.55f,.87f),new Vector3(.45f,-.62f,.87f),new Vector3(3.4f,-.62f,.87f)};for(int i=1;i<line.Length;i++){var delta=line[i]-line[i-1];var center=(line[i]+line[i-1])*.5f;int first=g.p.Count;g.Box(Vector3.zero,new Vector3(delta.magnitude,.065f,.055f),red);float angle=Mathf.Atan2(delta.y,delta.x)*Mathf.Rad2Deg;var rotation=Quaternion.Euler(0,0,angle);for(int k=first;k<g.p.Count;k++)g.p[k]=rotation*g.p[k]+center;}}else quad(0,0,7.2f,1.72f,.845f,.393f,.443f,.606f,.606f);if(side==1)for(int i=start;i<g.p.Count;i++)g.p[i]=Quaternion.Euler(0,180,0)*g.p[i];}
var mesh=new Mesh{name=detailed?"Hospital roadside raised cross atlas logo 220 triangles":"Hospital roadside distant atlas logo 28 triangles"};WriteG(mesh,g);UnityEngine.Object.DestroyImmediate(atlas);return mesh;}
